sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

	var body = request.body.data;
	var sysID = body.sys_id;
	var xurrentIMRIncident = body.x_xurre_imr_incident;

	if (!body || !sysID || !xurrentIMRIncident) {
		response.setStatus(400);
		response.setBody({ success: false, error: "Invalid Payload" });
		return;
	}

	try {
		var importGR = new GlideRecord('x_xurre_imr_u_import_incident');
		importGR.initialize();
		importGR.setValue('operation', 'update_x_xurre_imr_incident');
		importGR.setValue('incident_sys_id', sysID);
		importGR.setValue('x_xurre_imr_incident', xurrentIMRIncident);
		var importSysId = importGR.insert();

		importGR.get(importSysId);
		var resultStatus = importGR.getValue('result_status');
		var resultMessage = importGR.getValue('result_message');

		if (resultStatus !== 'success') {
			response.setStatus(400);
			response.setBody({ success: false, error: resultMessage });
			return;
		}

		response.setStatus(200);
		response.setBody({ success: true, message: "Mapping successful." });

	} catch (e) {
		response.setStatus(400);
		response.setBody({ success: false, error: "Mapping failed: " + e.message });
	}

})(request, response);
